parts[guide_index]=parts[guide_index].replace('</section>',decoder+'</section>')
links=''.join(f'<a href="#c{i+1}">{i+1:02d} {html.escape(title)}</a>' for i,(title,_) in enumerate(chapters))
js='''function decode(){const c=+document.querySelector('#chip').value,b=+document.querySelector('#bit').value,n=['U6','U7','U12','U13','U17','U18'][c-1],d=(c%2?0:4)+b-1;document.querySelector('#decoded').textContent='Long sync / 2 / '+c+' / '+b+' → '+n+' path: '+(b===5?'multiple implicated bits':'D'+d)+'. Check the chip and associated wiring/decode; this is not component proof.'}document.querySelectorAll('select').forEach(s=>s.addEventListener('change',decode));decode();'''
