(WEB/'content.json').write_text(json.dumps(dict(product_name='TS2068 Diagnostic Lab cartridge',version=VERSION,release_date=RELEASE_DATE,image_sha256=sha,chapters=chapters),indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
